# Let me try a completely different approach:
# Identify all 7s that are enclosed by 5s and fill them

def fill_enclosed(input_grid):
    rows = len(input_grid)
    cols = len(input_grid[0])
    output = [row[:] for row in input_grid]

    # Find all 7s that are reachable from the "outside"
    # Start from edge 7s and flood fill
    from collections import deque
    visited = set()
    queue = deque()

    for r in range(rows):
        for c in range(cols):
            if input_grid[r][c] == 7 and (r == 0 or r == rows-1 or c == 0 or c == cols-1):
                queue.append((r, c))
                visited.add((r, c))

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if (nr, nc) not in visited and input_grid[nr][nc] == 7:
                    visited.add((nr, nc))
                    queue.append((nr, nc))

    # All non-visited 7s are enclosed by 5s! Fill them.
    for r in range(rows):
        for c in range(cols):
            if input_grid[r][c] == 7 and (r, c) not in visited:
                output[r][c] = 5

    return output

